package com.deathbankutility;

import java.awt.Color;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * How the plugin learned the current deathbank state. The UI always shows this
 * tier — an inference is never presented as a fact.
 */
@RequiredArgsConstructor
@Getter
public enum Confidence
{
	/** Confirmed by a server signal: the retrieval interface, or a game message. */
	VERIFIED("Verified", Color.WHITE),
	/** Deduced from a local-player death and region mapping. */
	INFERRED("Inferred", Color.YELLOW),
	/** Carried over from a previous session with no confirming signal yet. */
	UNKNOWN("Unknown", Color.ORANGE);

	private final String label;
	private final Color color;
}

package com.deathbankutility;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.NPC;
import net.runelite.api.Point;
import net.runelite.api.TileObject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;
import net.runelite.client.util.ColorUtil;

/**
 * Outlines retrieval chests and NPCs while a deathbank is active and labels
 * them DEATHBANK, so the claim point visibly signals there is something inside.
 */
class DeathbankChestOverlay extends Overlay
{
	private static final String LABEL = "DEATHBANK";
	private static final int OUTLINE_WIDTH = 4;
	private static final int OUTLINE_FEATHER = 4;
	private static final int OBJECT_LABEL_Z_OFFSET = 130;
	private static final int NPC_LABEL_Z_OFFSET = 40;

	private final DeathbankUtilityPlugin plugin;
	private final DeathbankUtilityConfig config;
	private final ModelOutlineRenderer modelOutlineRenderer;

	@Inject
	DeathbankChestOverlay(DeathbankUtilityPlugin plugin, DeathbankUtilityConfig config, ModelOutlineRenderer modelOutlineRenderer)
	{
		this.plugin = plugin;
		this.config = config;
		this.modelOutlineRenderer = modelOutlineRenderer;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		boolean nothingToHighlight = plugin.getRetrievalObjects().isEmpty() && plugin.getRetrievalNpcs().isEmpty();
		boolean stateIsShown = plugin.getState().isActive() && !plugin.isAwaitingLoginConfirmation();
		if (nothingToHighlight || !config.highlightRetrievalPoints() || !stateIsShown)
		{
			return null;
		}

		graphics.setFont(FontManager.getRunescapeBoldFont());
		Color outlineColor = config.highlightColor();
		// The config color's alpha suits the outline; label text needs full opacity
		Color labelColor = ColorUtil.colorWithAlpha(outlineColor, 255);

		// Claim points for different services can share a room (Shura and Sister
		// Senga both stand in the Sisterhood Sanctuary), so highlight only the one
		// holding the items. With the location still unknown, every candidate is
		// highlighted rather than guessing wrong.
		RetrievalService service = plugin.getState().getService();
		boolean locationUnknown = service == null;

		plugin.getRetrievalObjects().stream()
			.filter(object -> locationUnknown || service.getClaimObjectIds().contains(object.getId()))
			.forEach(object -> renderObject(graphics, object, outlineColor, labelColor));
		plugin.getRetrievalNpcs().stream()
			.filter(npc -> locationUnknown || service.getClaimNpcIds().contains(npc.getId()))
			.forEach(npc -> renderNpc(graphics, npc, outlineColor, labelColor));
		return null;
	}

	private void renderObject(Graphics2D graphics, TileObject object, Color outlineColor, Color labelColor)
	{
		modelOutlineRenderer.drawOutline(object, OUTLINE_WIDTH, outlineColor, OUTLINE_FEATHER);
		renderLabel(graphics, object.getCanvasTextLocation(graphics, LABEL, OBJECT_LABEL_Z_OFFSET), labelColor);
	}

	private void renderNpc(Graphics2D graphics, NPC npc, Color outlineColor, Color labelColor)
	{
		modelOutlineRenderer.drawOutline(npc, OUTLINE_WIDTH, outlineColor, OUTLINE_FEATHER);
		renderLabel(graphics, npc.getCanvasTextLocation(graphics, LABEL, npc.getLogicalHeight() + NPC_LABEL_Z_OFFSET), labelColor);
	}

	private static void renderLabel(Graphics2D graphics, Point location, Color labelColor)
	{
		if (location == null)
		{
			return;
		}
		OverlayUtil.renderTextLocation(graphics, location, LABEL, labelColor);
	}
}

package com.deathbankutility;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.InfoBoxComponent;
import net.runelite.client.ui.overlay.components.TextComponent;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * Infobox-style indicator with a red background so an active deathbank
 * stands out, labeled with where the deathbank is.
 */
class DeathbankIndicatorOverlay extends Overlay
{
	private static final Color BACKGROUND = new Color(120, 0, 0, 170);
	private static final int BOX_SIZE = 40;
	private static final Dimension BOX_DIMENSION = new Dimension(BOX_SIZE, BOX_SIZE);
	private static final int LABEL_HEIGHT = 14;
	// Bottom-right corner of the box is plain background, clear of the skull
	private static final int COUNT_INSET = 3;

	private final Client client;
	private final DeathbankUtilityPlugin plugin;
	private final DeathbankUtilityConfig config;
	private final TooltipManager tooltipManager;

	@Inject
	DeathbankIndicatorOverlay(Client client, DeathbankUtilityPlugin plugin, DeathbankUtilityConfig config,
		TooltipManager tooltipManager)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.tooltipManager = tooltipManager;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		DeathbankState state = plugin.getState();
		boolean shouldShow = config.showIndicator() && state.isActive() && !plugin.isAwaitingLoginConfirmation();
		if (!shouldShow)
		{
			return null;
		}

		// The component centers its caption over the icon, where the pale skull
		// swallows it, so the count is drawn separately in the clear corner
		InfoBoxComponent box = new InfoBoxComponent();
		box.setImage(plugin.getIndicatorIcon());
		box.setBackgroundColor(BACKGROUND);
		box.setPreferredSize(BOX_DIMENSION);
		box.render(graphics);

		renderCount(graphics, countText(state), state.getConfidence().getColor());
		renderLocationLabel(graphics, state.shortLabel());
		addTooltipWhenHovered(box.getBounds(), state);
		return new Dimension(BOX_SIZE, BOX_SIZE + LABEL_HEIGHT);
	}

	private void addTooltipWhenHovered(Rectangle boxBounds, DeathbankState state)
	{
		Rectangle hitbox = new Rectangle(boxBounds);
		hitbox.translate(getBounds().x, getBounds().y);
		hitbox.height += LABEL_HEIGHT;

		net.runelite.api.Point mouse = client.getMouseCanvasPosition();
		if (!hitbox.contains(mouse.getX(), mouse.getY()))
		{
			return;
		}
		tooltipManager.add(new Tooltip(buildTooltip(state)));
	}

	private static String buildTooltip(DeathbankState state)
	{
		boolean stateIsUncertain = state.getConfidence() == Confidence.UNKNOWN;
		String verb = stateIsUncertain ? "Deathbank possibly active" : "Active deathbank";
		String heading = state.isLocationKnown()
			? verb + ": " + state.displayLabel()
			: verb + " (location unknown, open the chest to identify it)";
		return heading + "</br>" + describeContents(state)
			+ "</br>Any unsafe death anywhere deletes these items.";
	}

	private static String describeContents(DeathbankState state)
	{
		int stackCount = state.getItems().size();
		if (stackCount == 0)
		{
			return "Contents unknown, open the retrieval chest to check.";
		}

		String itemWord = stackCount == 1 ? "item" : "items";
		String basis = state.isItemsVerified() ? "verified" : "estimated";
		String qualifier = state.isItemsVerified() ? "" : "~";
		return qualifier + stackCount + " " + itemWord + " (" + basis + ")";
	}

	private static void renderCount(Graphics2D graphics, String count, Color color)
	{
		graphics.setFont(FontManager.getRunescapeBoldFont());
		FontMetrics metrics = graphics.getFontMetrics();

		TextComponent text = new TextComponent();
		text.setText(count);
		text.setColor(color);
		text.setOutline(true);
		text.setPosition(new Point(BOX_SIZE - COUNT_INSET - metrics.stringWidth(count), BOX_SIZE - COUNT_INSET));
		text.render(graphics);
	}

	private static void renderLocationLabel(Graphics2D graphics, String label)
	{
		graphics.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics metrics = graphics.getFontMetrics();

		TextComponent text = new TextComponent();
		text.setText(label);
		text.setColor(Color.WHITE);
		text.setOutline(true);
		text.setPosition(new Point((BOX_SIZE - metrics.stringWidth(label)) / 2, BOX_SIZE + LABEL_HEIGHT - 3));
		text.render(graphics);
	}

	private static String countText(DeathbankState state)
	{
		if (state.getItems().isEmpty())
		{
			return "!";
		}
		String qualifier = state.isItemsVerified() ? "" : "~";
		return qualifier + state.getItems().size();
	}
}

package com.deathbankutility;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Marks the items in the retrieval interface that came out of the looting bag,
 * so they can be picked back out and re-bagged without sorting by memory.
 */
class DeathbankLootingBagOverlay extends WidgetItemOverlay
{
	private static final int BADGE_SIZE = 17;

	private final DeathbankUtilityPlugin plugin;
	private final DeathbankUtilityConfig config;
	private final ItemManager itemManager;

	@Inject
	DeathbankLootingBagOverlay(DeathbankUtilityPlugin plugin, DeathbankUtilityConfig config, ItemManager itemManager)
	{
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		showOnInterfaces(InterfaceID.GRAVESTONE_RETRIEVAL, InterfaceID.GRAVESTONE_GENERIC);
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!config.highlightLootingBagItems() || !plugin.getState().cameFromLootingBag(itemId))
		{
			return;
		}

		// Outline the item's own shape rather than boxing the slot. Thin sprites like
		// bones are almost all edge, so the outline alone swallows them: the item is
		// drawn back over the top, leaving the colour as a halo around it.
		Rectangle bounds = widgetItem.getCanvasBounds();
		int quantity = widgetItem.getQuantity();
		BufferedImage outline = itemManager.getItemOutline(itemId, quantity, config.lootingBagColor());
		if (outline == null)
		{
			return;
		}

		graphics.drawImage(outline, bounds.x, bounds.y, null);
		graphics.drawImage(itemManager.getImage(itemId, quantity, quantity > 1), bounds.x, bounds.y, null);

		// A bag badge in the corner, where item charges sit, so the marking names
		// itself rather than relying on the colour being remembered
		BufferedImage badge = itemManager.getImage(ItemID.LOOTING_BAG);
		graphics.drawImage(badge, bounds.x + bounds.width - BADGE_SIZE,
			bounds.y + bounds.height - BADGE_SIZE, BADGE_SIZE, BADGE_SIZE, null);
	}
}

package com.deathbankutility;

import java.awt.Color;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import lombok.RequiredArgsConstructor;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import javax.swing.ImageIcon;
import javax.swing.SwingUtilities;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.QuantityFormatter;

/**
 * Side panel showing the current deathbank: status, confidence, and the
 * item grid (estimated until verified through the retrieval interface).
 */
class DeathbankPanel extends PluginPanel
{
	@RequiredArgsConstructor
	static class PanelItem
	{
		final String name;
		final int quantity;
		final AsyncBufferedImage image;
	}

	private static final int ITEMS_PER_ROW = 5;
	// Panel width less our borders, and less the margins Swing's HTML body adds on
	// top of the declared width, which is what pushed text past the panel edge
	private static final int TEXT_WRAP_WIDTH = PANEL_WIDTH - 60;
	private static final Dimension MAX_ROW = new Dimension(PANEL_WIDTH - 20, Integer.MAX_VALUE);
	private static final Color LOOTING_BAG_COLOR = new Color(0xFFD400);

	private final JLabel statusLabel = new JLabel();
	private final JLabel detailLabel = new JLabel();
	private final JLabel contentsLabel = new JLabel();
	private final JPanel itemGrid = new JPanel();
	private final JLabel lootingBagHeading = new JLabel();
	private final JPanel lootingBagGrid = new JPanel();
	private JPanel lootingBagSection;

	DeathbankPanel(ItemManager itemManager)
	{
		// The bag's own icon beside the heading, so the section names itself
		AsyncBufferedImage lootingBagIcon = itemManager.getImage(ItemID.LOOTING_BAG);
		lootingBagIcon.onLoaded(() -> SwingUtilities.invokeLater(() ->
		{
			lootingBagHeading.setIcon(new ImageIcon(ImageUtil.resizeImage(lootingBagIcon, 16, 16)));
			lootingBagHeading.repaint();
		}));

		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));

		statusLabel.setFont(FontManager.getRunescapeBoldFont());
		detailLabel.setFont(FontManager.getRunescapeSmallFont());
		contentsLabel.setFont(FontManager.getRunescapeSmallFont());
		contentsLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		JPanel header = new JPanel(new GridLayout(0, 1, 0, 4));
		header.setBorder(BorderFactory.createEmptyBorder(0, 0, 8, 0));
		header.add(statusLabel);
		header.add(detailLabel);
		header.add(contentsLabel);

		itemGrid.setLayout(new GridLayout(0, ITEMS_PER_ROW, 3, 3));
		lootingBagGrid.setLayout(new GridLayout(0, ITEMS_PER_ROW, 3, 3));
		lootingBagHeading.setFont(FontManager.getRunescapeSmallFont());
		lootingBagHeading.setForeground(LOOTING_BAG_COLOR);
		lootingBagHeading.setBorder(BorderFactory.createEmptyBorder(0, 0, 5, 0));
		lootingBagHeading.setIconTextGap(5);

		// The looting bag half is boxed and tinted so it reads as its own group to
		// re-bag, rather than more items in the same pile
		lootingBagSection = new JPanel(new BorderLayout());
		lootingBagSection.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createEmptyBorder(10, 0, 4, 2),
			BorderFactory.createCompoundBorder(
				BorderFactory.createMatteBorder(1, 1, 1, 1, LOOTING_BAG_COLOR),
				BorderFactory.createEmptyBorder(6, 6, 6, 6))));
		lootingBagSection.add(lootingBagHeading, BorderLayout.NORTH);
		lootingBagSection.add(lootingBagGrid, BorderLayout.CENTER);
		lootingBagSection.setVisible(false);

		JPanel grids = new JPanel();
		grids.setLayout(new BoxLayout(grids, BoxLayout.Y_AXIS));
		grids.add(itemGrid);
		grids.add(lootingBagSection);
		grids.setMaximumSize(MAX_ROW);

		JPanel gridWrapper = new JPanel(new BorderLayout());
		gridWrapper.add(grids, BorderLayout.NORTH);

		// BoxLayout will not stretch a bare JLabel, so the disclaimer needs a
		// full-width wrapper and an explicit wrap width to align with the rest
		JLabel disclaimer = new JLabel(wrapped("Early release: tracking can be wrong. Never treat a missing "
			+ "warning as proof you have no deathbank. Report bugs and request features from the plugin "
			+ "config's Feedback section."));
		disclaimer.setFont(FontManager.getRunescapeSmallFont());
		disclaimer.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		disclaimer.setVerticalAlignment(SwingConstants.TOP);

		// Same container type as the header: BorderLayout let the disclaimer force the
		// panel wider than the viewport, which clipped every label on the right
		JPanel footer = new JPanel(new GridLayout(0, 1));
		footer.setBorder(BorderFactory.createEmptyBorder(12, 0, 0, 0));
		footer.add(disclaimer);
		footer.setAlignmentX(LEFT_ALIGNMENT);
		footer.setMaximumSize(MAX_ROW);

		header.setAlignmentX(LEFT_ALIGNMENT);
		header.setMaximumSize(MAX_ROW);
		gridWrapper.setAlignmentX(LEFT_ALIGNMENT);
		gridWrapper.setMaximumSize(MAX_ROW);

		add(header);
		add(gridWrapper);
		add(footer);

		showInactive();
	}

	void update(DeathbankState state, List<PanelItem> items, List<PanelItem> lootingBagItems, boolean awaitingConfirmation)
	{
		if (awaitingConfirmation)
		{
			showChecking();
			return;
		}
		if (!state.isActive())
		{
			showInactive();
			return;
		}

		statusLabel.setText(wrapped("Deathbank active: " + state.displayLabel()));
		statusLabel.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
		detailLabel.setText(wrapped("Confidence: " + state.getConfidence().getLabel()
			+ ". Any unsafe death anywhere deletes these items." + feeSentence(state)));
		contentsLabel.setText(contentsText(state, items));

		// Split so the looting bag half can be re-bagged as a group rather than
		// picked out of one undifferentiated pile
		itemGrid.removeAll();
		items.forEach(item -> itemGrid.add(buildItemCell(item)));

		lootingBagGrid.removeAll();
		lootingBagItems.forEach(item -> lootingBagGrid.add(buildItemCell(item)));
		lootingBagHeading.setText("From your looting bag");
		lootingBagSection.setVisible(!lootingBagItems.isEmpty());

		itemGrid.revalidate();
		itemGrid.repaint();
		lootingBagGrid.revalidate();
		lootingBagGrid.repaint();
	}

	private void showChecking()
	{
		statusLabel.setText("Checking for a deathbank...");
		statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		detailLabel.setText(wrapped("Waiting for the game to confirm whether anything is stored."));
		contentsLabel.setText("");
		clearGrids();
	}

	private void showInactive()
	{
		statusLabel.setText("No active deathbank");
		statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		detailLabel.setText(wrapped("Die at content with an item retrieval service and it will show up here. "
			+ "Only a death that actually sends your items there counts."));
		contentsLabel.setText("");
		clearGrids();
	}

	private void clearGrids()
	{
		itemGrid.removeAll();
		lootingBagGrid.removeAll();
		lootingBagSection.setVisible(false);
		itemGrid.revalidate();
		itemGrid.repaint();
		lootingBagGrid.revalidate();
		lootingBagGrid.repaint();
	}

	private static String wrapped(String text)
	{
		return "<html><body style='margin:0;width:" + TEXT_WRAP_WIDTH + "px'>" + text + "</body></html>";
	}

	/**
	 * An estimate cannot include the looting bag unless the client has been shown its
	 * contents, so say so rather than letting the count look complete.
	 */
	private static String unknownLootingBagWarning(DeathbankState state)
	{
		// Contents read from the chest are the whole truth, bag included, so the
		// caveat only applies while the list is still an estimate
		if (state.isItemsVerified() || !state.getLootingBagItems().isEmpty())
		{
			return "";
		}
		return " Anything in your looting bag is not counted here, the game never showed it to the client.";
	}

	private static String describeStacks(int stackCount)
	{
		return stackCount + (stackCount == 1 ? " item stack." : " item stacks.");
	}

	private static String feeSentence(DeathbankState state)
	{
		if (state.getService() == null)
		{
			return "";
		}
		return " Reclaim fee: " + state.getService().getFeeText() + ".";
	}

	private static String contentsText(DeathbankState state, List<PanelItem> items)
	{
		if (items.isEmpty())
		{
			return wrapped("Contents unknown, open the retrieval chest to verify.");
		}
		String basis = state.isItemsVerified()
			? "Verified from the retrieval interface:"
			: "Estimated from your gear at death:";
		return wrapped(basis + " " + describeStacks(items.size()) + unknownLootingBagWarning(state));
	}

	private static JLabel buildItemCell(PanelItem item)
	{
		JLabel cell = new JLabel();
		cell.setPreferredSize(new Dimension(36, 32));
		cell.setHorizontalAlignment(JLabel.CENTER);
		cell.setToolTipText(item.name + " x " + QuantityFormatter.formatNumber(item.quantity));
		item.image.addTo(cell);
		return cell;
	}
}

package com.deathbankutility;

import java.util.List;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Everything the plugin believes about the player's deathbank, persisted
 * per RuneScape profile as JSON.
 */
@Data
@NoArgsConstructor
public class DeathbankState
{
	@Data
	@NoArgsConstructor
	@AllArgsConstructor
	public static class ItemStack
	{
		private int id;
		private int quantity;
	}

	private static final int MAX_SHORT_LABEL_CHARS = 10;

	private boolean active;
	private Confidence confidence = Confidence.UNKNOWN;
	private RetrievalService service;
	private String windowTitle;
	private List<ItemStack> items = List.of();
	private boolean itemsVerified;
	/** What the looting bag held when it went in, so those items can be marked for re-bagging. */
	private List<ItemStack> lootingBagItems = List.of();

	static DeathbankState unknown()
	{
		return inactive(Confidence.UNKNOWN);
	}

	static DeathbankState inactive(Confidence confidence)
	{
		DeathbankState state = new DeathbankState();
		state.confidence = confidence;
		return state;
	}

	static DeathbankState active(Confidence confidence, RetrievalService service, String windowTitle,
		List<ItemStack> items, boolean itemsVerified)
	{
		return active(confidence, service, windowTitle, items, itemsVerified, List.of());
	}

	static DeathbankState active(Confidence confidence, RetrievalService service, String windowTitle,
		List<ItemStack> items, boolean itemsVerified, List<ItemStack> lootingBagItems)
	{
		DeathbankState state = new DeathbankState();
		state.active = true;
		state.confidence = confidence;
		state.service = service;
		state.windowTitle = windowTitle;
		state.items = items;
		state.itemsVerified = itemsVerified;
		state.lootingBagItems = lootingBagItems;
		return state;
	}

	boolean cameFromLootingBag(int itemId)
	{
		return lootingBagItems.stream().anyMatch(stack -> stack.getId() == itemId);
	}

	DeathbankState withConfidence(Confidence newConfidence)
	{
		DeathbankState copy = new DeathbankState();
		copy.active = active;
		copy.confidence = newConfidence;
		copy.service = service;
		copy.windowTitle = windowTitle;
		copy.items = items;
		copy.itemsVerified = itemsVerified;
		copy.lootingBagItems = lootingBagItems;
		return copy;
	}

	boolean isLocationKnown()
	{
		return service != null || hasWindowTitle();
	}

	String displayLabel()
	{
		if (service != null)
		{
			return service.getDisplayName();
		}
		return hasWindowTitle() ? windowTitle.trim() : "location unknown";
	}

	String shortLabel()
	{
		if (service != null)
		{
			return service.getShortName();
		}
		return hasWindowTitle() ? truncate(windowTitle.trim()) : "?";
	}

	private boolean hasWindowTitle()
	{
		return windowTitle != null && !windowTitle.trim().isEmpty();
	}

	private static String truncate(String label)
	{
		return label.length() <= MAX_SHORT_LABEL_CHARS ? label : label.substring(0, MAX_SHORT_LABEL_CHARS);
	}
}

package com.deathbankutility;

import java.awt.Color;
import java.time.Instant;
